const STORAGE='lumo-demo-v2';
let accounts=[{name:'Admin Lumo',role:'admin',rateCents:100},{name:'sujif',role:'seller',rateCents:100},{name:'joys',role:'seller',rateCents:100}];
let activeAccount='Admin Lumo';
sales.forEach(s=>{s.payRateCents=0;s.payCents=0;s.costCents=Object.entries(s.products).reduce((n,[name,q])=>n+Math.round(products.find(p=>p.name===name).cost*100)*q,0);s.feeCents=0});
try{const saved=JSON.parse(localStorage.getItem(STORAGE));if(saved){accounts=saved.accounts;sales=saved.sales;saved.stocks.forEach(p=>{let existing=products.find(x=>x.name===p.name);if(existing)existing.stock=p.stock})}}catch{}
const account=()=>accounts.find(a=>a.name===activeAccount);
const pocketFor=name=>sales.filter(s=>s.seller===name).reduce((n,s)=>n+(s.payCents||0),0);
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({accounts,sales,stocks:products}))}catch{toast('Stockage local indisponible : garde cette page ouverte')}}
function updatePocket(){const a=account();document.getElementById('pocket-total').textContent=fmt(pocketFor(a.name)/100);document.getElementById('pocket-rate').textContent=fmt(a.rateCents/100)+' / parfum';document.getElementById('pocket-description').textContent=a.name+' · gains des ventes enregistrées';const units=Object.values(selected).reduce((n,q)=>n+q,0);let preview=document.getElementById('pay-preview');if(!preview){preview=document.createElement('p');preview.id='pay-preview';preview.className='payout-value';document.getElementById('summary-price').parentElement.after(preview)}preview.textContent='Gain pour cette vente : '+fmt(units*a.rateCents/100)}
const baseSummary=renderSummary;renderSummary=function(){baseSummary();updatePocket()};
function updateMetrics(){let ca=0,cost=0,pay=0,fees=0;for(const s of sales){ca+=Math.round(s.price*100);cost+=s.costCents||0;pay+=s.payCents||0;fees+=s.feeCents||0}let values=document.querySelectorAll('.kpi-val');[fmt(ca/100),fmt((ca-cost)/100),fmt((ca-cost-pay-fees)/100),String(sales.length)].forEach((v,i)=>values[i].textContent=v);document.querySelectorAll('.kpi-foot')[0].textContent='Total des ventes de démonstration';document.querySelectorAll('.kpi-foot')[2].textContent=fmt(pay/100)+' de rémunérations déduites · frais TikTok à configurer';document.querySelectorAll('.kpi-foot')[3].textContent='Toutes les ventes de la démo';document.querySelector('.seller-list').innerHTML=accounts.map(a=>{let rows=sales.filter(s=>s.seller===a.name),total=rows.reduce((n,s)=>n+s.price,0);return `<div class="seller-row"><div class="avatar">${esc(a.name.slice(0,2).toUpperCase())}</div><div class="seller-meta"><strong>${esc(a.name)}</strong><span>${rows.length} ventes · pocket ${fmt(pocketFor(a.name)/100)}</span></div><div class="seller-total">${fmt(total)}<small>CA généré</small></div><div class="progress"><i style="width:${ca?total*10000/ca:0}%"></i></div></div>`}).join('');document.querySelector('.seller-list').nextElementSibling.lastElementChild.textContent=fmt(sales.length?ca/100/sales.length:0);document.querySelectorAll('.panels .panel-caption')[0].textContent='Montants des ventes de démonstration';document.querySelectorAll('.panels .panel-caption')[1].textContent='CA et gains indicatifs par compte';document.querySelector('.panels .period').disabled=true;document.querySelector('.panels .period').innerHTML='<option>Ventes de la démo</option>';document.querySelectorAll('.panels .period')[1].textContent=sales.length+' ventes';document.querySelector('.chart-legend .legend-total').textContent=fmt(ca/100);const groups={};sales.forEach(s=>{let d=s.date.slice(0,10);groups[d]??={trends:0,shop:0};groups[d][s.shop==='Lumo Shop'?'shop':'trends']+=s.price});let dates=Object.keys(groups).sort().slice(-7),max=Math.max(1,...dates.map(d=>groups[d].trends+groups[d].shop));document.querySelector('.chart').innerHTML=dates.map(d=>{let g=groups[d];return `<div class="bar-group"><div class="bar-stack" title="${esc(d)} : ${fmt(g.trends+g.shop)}"><i class="bar" style="height:${(g.trends+g.shop)/max*100}%"></i><i class="bar alt" style="height:${g.shop/max*100}%"></i></div><span class="bar-label">${d.slice(8)}/${d.slice(5,7)}</span></div>`}).join('')}
const baseSales=renderSales;renderSales=function(){baseSales();document.querySelectorAll('[data-delete]').forEach(el=>el.onclick=()=>{if(account().role!=='admin')return;if(!confirm('Supprimer la vente ? Le stock sera rétabli et son gain retiré du pocket.'))return;const sale=sales.find(s=>s.id==el.dataset.delete);Object.entries(sale.products).forEach(([n,q])=>products.find(p=>p.name===n).stock+=q);sales=sales.filter(s=>s!==sale);refresh();toast('Vente supprimée, stock et pocket ajustés')});document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>{if(account().role!=='admin')return;const s=sales.find(s=>s.id==el.dataset.edit),value=prompt('Nouveau prix (€) :',s.price);if(value===null)return;const price=Number(value.replace(',','.'));if(!Number.isFinite(price)||price<=0){toast('Saisis un prix positif');return}s.price=Math.round(price*100)/100;refresh();toast('Prix corrigé · gain par flacon inchangé')});document.querySelectorAll('[data-verify]').forEach(el=>el.onchange=()=>{if(account().role!=='admin')return;sales.find(s=>s.id==el.dataset.verify).verified=el.checked;refresh()});};
function refresh(){renderStock();renderProducts();renderSummary();renderSales();updateMetrics();persist()}
setScreen=function(id){if(account().role!=='admin')id='sales-entry';const screen=id==='stock'||id==='sales-list'?'dashboard':id;document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('active',s.id===screen));document.querySelectorAll('.nav-btn,.mobile-bottom button').forEach(b=>b.classList.toggle('active',b.dataset.target===id));document.getElementById('crumb-label').textContent=screen==='dashboard'?'Vue d’ensemble':'Nouvelle vente';if(id!==screen)document.getElementById(id).scrollIntoView({behavior:'smooth',block:'start'});else window.scrollTo({top:0,behavior:'smooth'})};
function populateAccounts(){const options=accounts.map(a=>`<option>${esc(a.name)}</option>`).join('');document.getElementById('demo-account').innerHTML=options;document.getElementById('demo-account').value=activeAccount;document.getElementById('sale-seller').innerHTML=options;document.getElementById('sale-seller').value=activeAccount;document.getElementById('seller-filter').innerHTML='<option value="">Tous les vendeurs</option>'+options}
document.getElementById('demo-account').onchange=e=>{activeAccount=e.target.value;document.body.classList.toggle('seller-mode',account().role==='seller');document.getElementById('sale-seller').value=activeAccount;document.querySelector('.profile strong').textContent=activeAccount;document.querySelector('.profile span').textContent=account().role==='admin'?'Administrateur':'Vendeur';document.querySelector('.profile .avatar').textContent=activeAccount.slice(0,2).toUpperCase();selected={};refresh();setScreen(account().role==='admin'?'dashboard':'sales-entry')};
document.getElementById('save-sale').onclick=()=>{let buyer=document.getElementById('sale-buyer').value.trim(),price=Number(document.getElementById('sale-price').value),date=document.getElementById('sale-date').value,link=document.getElementById('sale-link').value.trim();let items=Object.fromEntries(Object.entries(selected).filter(([,q])=>q>0));if(!buyer||!date||!Number.isFinite(price)||price<=0||!Object.keys(items).length){toast('Renseigne le pseudo, la date, les parfums et un prix positif');return}if(link){try{const u=new URL(link);if(!['https:','http:'].includes(u.protocol))throw 0}catch{toast('Le lien du bordereau doit être une URL valide');return}}for(const [name,q] of Object.entries(items)){if(q>products.find(p=>p.name===name).stock){toast('Stock insuffisant pour '+name);return}}const units=Object.values(items).reduce((n,q)=>n+q,0),rate=account().rateCents;const cost=Object.entries(items).reduce((n,[name,q])=>n+Math.round(products.find(p=>p.name===name).cost*100)*q,0);for(const [name,q] of Object.entries(items))products.find(p=>p.name===name).stock-=q;sales.unshift({id:Date.now(),date,buyer,price:Math.round(price*100)/100,seller:activeAccount,shop:document.getElementById('sale-shop').value,products:items,verified:false,link,payRateCents:rate,payCents:rate*units,costCents:cost,feeCents:0});selected={};['sale-buyer','sale-price','sale-link'].forEach(id=>document.getElementById(id).value='');document.getElementById('sale-date').value=localDate();refresh();toast('Vente enregistrée · +'+fmt(rate*units/100)+' dans ton pocket')};
function renderRates(){document.getElementById('rate-list').innerHTML=accounts.map((a,i)=>`<div class="rate-row"><label for="rate-${i}">${esc(a.name)}<small>Pocket : ${fmt(pocketFor(a.name)/100)}</small></label><div><input class="input" id="rate-${i}" aria-label="Tarif par parfum pour ${esc(a.name)}" type="number" min="0" max="10000" step="0.01" value="${(a.rateCents/100).toFixed(2)}"><small>€ / parfum</small></div><button class="btn btn-primary" data-rate="${i}">Appliquer</button></div>`).join('');document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{if(account().role!=='admin')return;let i=Number(b.dataset.rate),raw=document.getElementById('rate-'+i).value,value=Number(raw);if(!raw||!Number.isFinite(value)||value<0||value>10000){toast('Saisis un tarif entre 0 et 10 000 €');return}accounts[i].rateCents=Math.round(value*100);refresh();renderRates();toast('Tarif mis à jour pour les prochaines ventes')})}
document.getElementById('open-pay').onclick=()=>{if(account().role!=='admin')return;renderRates();document.getElementById('pay-dialog').showModal()};document.getElementById('close-pay').onclick=()=>document.getElementById('pay-dialog').close();document.getElementById('add-seller').onclick=()=>{if(account().role!=='admin')return;const name=document.getElementById('new-seller').value.trim();if(!name||accounts.some(a=>a.name.toLowerCase()===name.toLowerCase())){toast('Choisis un nom unique');return}accounts.push({name,role:'seller',rateCents:100});populateAccounts();refresh();renderRates();document.getElementById('new-seller').value='';toast('Compte de démo créé · pocket 0 €')};
document.querySelector('.stock-panel .btn').onclick=()=>toast('Stocks mis à jour automatiquement par les ventes de démo');document.querySelector('.shop-switch select').onchange=()=>toast('Choisis la boutique lors de la saisie de chaque vente');document.querySelector('.heading .eyebrow').textContent=new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});document.querySelector('.heading .subheading').textContent='Vos ventes, vos stocks et les gains de votre équipe.';
populateAccounts();refresh();
